<?php
declare(strict_types=1);
header('Cache-Control: no-store');header('Referrer-Policy: no-referrer');header('X-Content-Type-Options: nosniff');header('X-Frame-Options: DENY');header('X-Robots-Tag: noindex, nofollow');
header("Content-Security-Policy: default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'");
$config=require __DIR__.'/metricas-config.php';
$key=$_GET['chave']??'';
if (!is_string($key)||!hash_equals($config['key_hash'],hash('sha256',$key))) { http_response_code(404);exit('Página não encontrada.'); }
require_once __DIR__.'/metricas-lib.php';
$range=(int)($_GET['dias']??30);if (!in_array($range,[7,30,90],true)) $range=30;
$cutoff=(new DateTimeImmutable('-'.($range-1).' days',new DateTimeZone('America/Sao_Paulo')))->format('Y-m-d');
$data=array_filter(essenes_metrics_read(),static fn($day)=>$day>=$cutoff,ARRAY_FILTER_USE_KEY);
$totals=array_fill_keys(ESSENES_METRIC_EVENTS,0);
foreach($data as $counts)foreach($totals as $event=>$value)$totals[$event]+=(int)($counts[$event]??0);
function out(string $text): string { return htmlspecialchars($text,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
$labels=['page_view'=>'Páginas vistas','home_view'=>'Acessos à home','contact_view'=>'Acessos ao contato','contact_customized'=>'Preparações personalizadas','whatsapp_click'=>'Cliques no WhatsApp'];
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Procura pelo atendimento | Essenes</title><style>body{margin:0;background:#f4f2e8;color:#1d4030;font:15px/1.6 system-ui,Arial}main{max-width:1100px;margin:auto;padding:32px 22px}h1{font:600 clamp(32px,5vw,46px)/1.15 Georgia,serif;margin:10px 0 18px}p{max-width:80ch;color:#52624f}.top{font-size:12px;letter-spacing:.15em}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(165px,1fr));gap:13px;margin:25px 0}.card{border:1px solid #d2dbc7;border-radius:12px;background:#fffdf8;padding:20px}.card strong{display:block;font-size:34px;line-height:1.4}.card span{font-size:12px}select,button{font:inherit;padding:8px 12px;border:1px solid #aabb98;border-radius:6px;background:#fffdf8;color:#244b34;min-height:42px}button{background:#244b34;color:#fff;cursor:pointer}label{display:inline-block;margin-right:7px}.scroll{overflow-x:auto;margin-top:25px}table{border-collapse:collapse;width:100%;min-width:620px;background:#fffdf8}th,td{text-align:left;padding:12px;border-bottom:1px solid #dde4d5;font-size:13px}th{background:#e8eddf}small{display:block;margin-top:25px;color:#68755f}.note{padding:18px;border-left:3px solid #b89a60;background:#ebeedd}a{color:#315d3c}</style></head><body><main><div class="top">ESSENES · PAINEL PRIVADO</div><h1>Como está a procura pelo atendimento?</h1><p>Contagens agregadas de eventos no site. Atualizado ao recarregar esta página. Fuso de referência: Brasília.</p><form method="get"><input type="hidden" name="chave" value="<?= out($key) ?>"><label for="dias">Período</label><select id="dias" name="dias"><?php foreach([7,30,90] as $option):?><option value="<?= $option ?>"<?= $range===$option?' selected':'' ?>>Últimos <?= $option ?> dias</option><?php endforeach;?></select> <button type="submit">Atualizar</button></form><div class="cards"><?php foreach($labels as $event=>$label):?><div class="card"><strong><?= $totals[$event] ?></strong><span><?= out($label) ?></span></div><?php endforeach;?></div><p class="note">Cliques não são mensagens enviadas nem sessões agendadas. Uma pessoa pode gerar vários acessos e cliques. As contagens não representam visitantes únicos e podem ser afetadas por robôs, bloqueadores ou falhas de rede.</p><div class="scroll"><table><thead><tr><th>Data</th><?php foreach($labels as $label):?><th><?= out($label) ?></th><?php endforeach;?></tr></thead><tbody><?php if(!$data):?><tr><td colspan="6">Sem contagens neste período. Os eventos começam após a instalação do pacote em uma hospedagem com PHP e gravação disponível.</td></tr><?php endif;?><?php foreach(array_reverse($data,true) as $day=>$counts):?><tr><td><?= out($day) ?></td><?php foreach($labels as $event=>$label):?><td><?= (int)($counts[$event]??0) ?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><small>O sistema conserva até 90 dias de contagens. Não registra identificadores de visitantes, IP, nomes, mensagens, endereço da página ou notas da Roda da Vida no arquivo de contagem. A hospedagem pode manter seus próprios registros operacionais. Guarde o link deste painel em local privado.</small></main></body></html>
